import glob, os, xml.etree.ElementTree as ET
roots={os.path.dirname(f) for f in glob.glob('**/build/test-results/**/TEST-*.xml', recursive=True)}
for root in sorted(roots):
    total=fail=err=skip=files=0
    for f in glob.glob(root+'/TEST-*.xml'):
        r=ET.parse(f).getroot(); files+=1
        total += int(r.attrib.get('tests',0)); fail += int(r.attrib.get('failures',0)); err += int(r.attrib.get('errors',0)); skip += int(r.attrib.get('skipped',0))
    print(root, files, total, fail, err, skip)
